import{_ as e,c as o,o as s,b0 as a}from"./chunks/framework.BWMBvyU7.js";const n="/programming-docs/assets/104Z34a7-0-1777982327939-33.B3D5LOIe.jpg",l="/programming-docs/assets/104Z31635-1-1777982338530-35.vTfwm6rq.jpg",w=JSON.parse('{"title":"LV570-Windows下C程序内存布局","description":null,"frontmatter":{"title":"LV570-Windows下C程序内存布局","date":"2026-05-05T19:58:08.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d44371520337bc3ed7adb","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T19:58:08.823Z","fulluuid":"bc3ed7adb35044b7a93dafe6dff9931e","useduuid":"bc3ed7adb"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d44371520337bc3ed7adb.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV570-Windows下C程序内存布局.md","lastUpdated":1777987950000}'),i={name:"sdoc/Language/c/memory/126d44371520337bc3ed7adb.md"};function t(r,d,c,p,_,m){return s(),o("div",null,[...d[0]||(d[0]=[a('<h1 id="lv570-windows下c程序内存布局" tabindex="-1">LV570-Windows下C程序内存布局 <a class="header-anchor" href="#lv570-windows下c程序内存布局" aria-label="Permalink to &quot;LV570-Windows下C程序内存布局&quot;">​</a></h1><p>在 32 位环境下，Windows 默认会将高地址的 2GB 空间分配给内核（也可以配置为 1GB），而将剩下的 2GB 空间分配给用户程序。</p><p>不像 Linux，Windows 是闭源的，有版权保护，资料较少，不好深入研究每一个细节，至今仍有一些内部原理不被大家知晓。关于 Windows 地址空间的内存分布，官网上只给出了简单的说明：</p><ul><li>对于 32 位程序，内核占用较高的 2GB，剩下的 2GB 分配给用户程序；</li><li>对于 64 位程序，内核占用最高的 248TB，用户程序占用最低的 8TB。</li></ul><p>下图是一个典型的 Windows 32 位程序的内存分布：</p><p><img src="'+n+'" alt="Windows 32 位程序内存分布"></p><p>可以看到，Windows 的地址空间被分配给了各种 exe、dll 文件、堆、栈。其中 exe 文件一般位于 0x00400000 起始的地址；一部分 DLL 位于 0x10000000 起始的地址，如运行库 dll；还有一部分 DLL 位于接近 0x80000000 的位置，如系统 dll，Ntdll.dll、Kernel32.dll。</p><p>栈的位置则在 0x00030000 和 exe 文件后面都有分布，可能有读者奇怪为什么 Windows 需要这么多栈呢？我们知道，每个线程的栈都是独立的，所以一个进程中有多少个线程，就有多少个对应的栈，对于 Windows 来说，每个线程默认的栈大小是 1MB。</p><p>在分配完上面这些地址以后，Windows 的地址空间已经是支离破碎了。当程序向系统申请堆空间时，只好从这些剩下的还有没被占用的地址上分配。</p><p>Windows 64 位程序的地址空间分布情况如下图所示：</p><p><img src="'+l+'" alt="Windows 64 位程序内存分布"></p><p>由于官方资料不足，我们不再深入了解 Windows 64 位程序的具体内存分布。</p>',12)])])}const g=e(i,[["render",t]]);export{w as __pageData,g as default};
